    if (toolOpen && toolOpen !== b.dataset.tab && BAR_ITEMS[toolOpen] && !BAR_ITEMS[toolOpen].view && !WORK_TABS.includes(toolOpen)) closeTool();
    if (BAR_ITEMS[b.dataset.tab]) return openBarItem(b.dataset.tab, b);
