    D.svBtn = h('button', { class: 'btn small sv-toggle', 'aria-pressed': 'false', onclick: () => { SV.open = !SV.open; store.set('savedOpen', SV.open); renderShelf(); } }, '📋 Saved tasks');
    D.shelf = h('div', { class: 'sv-shelf hidden' });
