  const appRecipes = (a) => (APP_RECIPES[a.id]?.r || []).map((x) => (typeof x === 'string' ? AUTO_RECIPES.find((y) => y.name === x) : x)).filter(Boolean);
  // One tap: the recipe as it is, through the same route the builder saves with.
