    const live = (s) => s.values[sStatus?.id] !== sDone;
    const cur = sprints.find((x) => x.id === PR.sprint) || sprints.find((x) => sStatus && x.values[sStatus.id] === sStatus.choices.find((c) => c.label === 'Active')?.id)
