      VK.q = q.value;
      const n = q.value.trim().toLowerCase();
      const f = VK.filter;
      const hits = VK.items
        .filter((x) => !f || (x.link?.type === f.type && x.link.id === f.id))
        .filter((x) => !n || [x.title, x.site, x.user, x.where, vaultLinkName(x.link)].some((v) => (v || '').toLowerCase().includes(n)))
