    const reset = h('button', { class: 'link', 'data-label': '1' }, 'Forgot it? Start over');
    reset.addEventListener('click', () => confirmClick(reset, () => { VK.resetting = true; renderTool(); }));
    if (VK.resetting) return vaultSetup(true);
